return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-25T17:31:44+00:00','po-revision-date'=>'2026-09-25T17:31:44+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A fast, privacy-respecting live chat for your website. Answers visitors with AI when you are busy, hands them to you when they need a person, and emails you anything you miss. Under 10 KB on the page and no requests at all until somebody opens it.'=>'Szybki czat na żywo dla Twojej witryny, który szanuje prywatność. Odpowiada odwiedzającym za pomocą sztucznej inteligencji, gdy jesteś zajęty, przekazuje ich Tobie, gdy potrzebują człowieka, oraz wysyła Ci mailem wszystko, co przegapisz. Zajmuje mniej niż 10 KB na stronie i nie generuje żadnych żądań, dopóki ktoś go nie otworzy.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'Ustawienia','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'To nie wygląda na klucz Zinn® Chat. Skopiuj go ze strony czatu na żywo w panelu Zinn Digital® – zaczyna się od zc_.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'Dodaj swój klucz czatu przed włączeniem czatu — bez niego widżet nie będzie miał się z czym połączyć.','Live chat for this site. Visitors get an answer straight away, you get anything you miss by email, and the whole thing is under 10 KB on the page.'=>'Czat na żywo dla tej witryny. Odwiedzający otrzymują odpowiedź natychmiast, Ty otrzymujesz wszystko, co ominiesz, e-mailem, a całość zajmuje mniej niż 10 KB na stronie.','The chat is live on this site.'=>'Czat jest aktywny w tej witrynie.','The chat is switched off. Nothing is loaded on your site.'=>'Czat jest wyłączony. Na Twojej stronie nic nie jest ładowane.','Chat key'=>'Klucz czatu','Copy this from the Live chat page of your %s.'=>'Skopiuj to ze strony czatu na żywo w Twoim %s.','Zinn Digital® dashboard'=>'Pulpit Zinn Digital®','Show the chat'=>'Pokaż czat','Show the chat window to visitors of this site'=>'Pokaż okno czatu odwiedzającym tę witrynę','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'Zanim to zaznaczysz, wtyczka nie dodaje do Twoich stron absolutnie nic – żadnego skryptu, żadnego ciasteczka ani żadnych żądań.','%s — guides and services'=>'%s — poradniki i usługi','User guides'=>'Przewodniki użytkownika','Read the %s user guide'=>'Przeczytaj przewodnik użytkownika %s','Hide this'=>'Ukryj to','Zinn® hosting for WordPress'=>'Hosting Zinn® dla WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, codzienne kopie zapasowe, darmowa migracja i panel sterowania stworzony dla osób prowadzących więcej niż jedną witrynę.','The Zinn® marketplace'=>'Rynek Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupuj i sprzedawaj gotowe strony, domeny oraz miejsca na linki, trzymając środki bezpiecznie do momentu, aż obie strony będą zadowolone.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zatrudnij profesjonalistów, którzy zajmują się tym na co dzień','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Nasza globalna platforma dla freelancerów: przeglądaj ponad 10 000 gotowych usług od pisarzy, projektantów, programistów i specjalistów SEO lub opublikuj projekt i pozwól im składać oferty.','See the Zinn Digital® release notes.'=>'Zapoznaj się z informacjami o wydaniu Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Pobrana aktualizacja nie przeszła kontroli spójności i nie została zainstalowana.','Everything here keeps working for nothing, for ever. Pro is for when one person answering, and a month of history, stops being enough.'=>'Wszystko tutaj działa dalej za darmo, na zawsze. Wersja Pro jest przeznaczona na moment, gdy jedna odpowiadająca osoba i miesiąc historii przestają wystarczać.','As many colleagues answering at once as you like — the free plugin allows one.'=>'Dowolna liczba kolegiów odpowiadających jednocześnie — darmowa wtyczka pozwala na jedną.','Every conversation kept for ever, instead of thirty days.'=>'Każda konwersacja zachowana na zawsze, zamiast przez trzydzieści dni.','Your own name on the chat window, with ours removed.'=>'Twoje własne imię w oknie czatu, z usuniętym naszym.','Saved replies, transfer a conversation to a colleague, and business hours.'=>'Zapisane odpowiedzi, przekazywanie konwersacji współpracownikowi oraz godziny pracy.','5,000 AI answers a month rather than 100.'=>'5000 odpowiedzi AI miesięcznie zamiast 100.','Choose exactly which pages the chat appears on — or hide it from the checkout.'=>'Wybierz dokładnie, na których stronach ma się pojawiać czat – lub ukryj go na stronie płatności.','One licence covers three of your sites; ten-site licences are available.'=>'Jedna licencja obejmuje trzy Twoje strony; dostępne są licencje na dziesięć stron.','See what Pro costs'=>'Zobacz cennik planu Pro','Already host a site with Zinn Digital®? Pro is included free — your key is on the %s.'=>'Masz już witrynę w Zinn Digital®? Wersja Pro jest wliczona w cenę – Twój klucz znajduje się na %s.','Licences page of your dashboard'=>'Strona licencji w Twoim panelu sterowania','Your licence is active.'=>'Twoja licencja jest aktywna.','Your licence has run out but everything still works for a short while. Renew it to keep receiving updates.'=>'Twoja licencja wygasła, ale wszystko działa jeszcze przez krótki czas. Odnów ją, aby nadal otrzymywać aktualizacje.','We do not recognise that licence key. Copy it again from the Licences page of your Zinn Digital® dashboard.'=>'Nie rozpoznajemy tego klucza licencji. Skopiuj go ponownie ze strony Licencje w panelu Zinn Digital®.','That key is for a different Zinn® plugin. The one you want is on the Licences page of your dashboard, next to Zinn® Chat Pro.'=>'Ten klucz jest przeznaczony dla innej wtyczki Zinn®. Ta, której szukasz, znajduje się na stronie Licencje w Twoim panelu sterowania, obok Zinn® Chat Pro.','Your licence has expired. Renew it from your Zinn Digital® dashboard to switch the Pro features back on.'=>'Twoja licencja wygasła. Odnów ją w panelu Zinn Digital®, aby ponownie włączyć funkcje Pro.','This licence has been cancelled.'=>'Ta licencja została anulowana.','This licence is on hold. Please get in touch and we will sort it out.'=>'Ta licencja jest zawieszona. Prosimy o kontakt, a my to rozwiążemy.','There is a billing problem on your Zinn Digital® account. Once it is settled the licence works again straight away.'=>'Wystąpił problem z rozliczeniami na Twoim koncie Zinn Digital®. Po jego rozwiązaniu licencja zacznie ponownie działać natychmiast.','This licence came free with your Zinn® hosting, and that hosting has ended. Buy a licence, or start hosting with us again, to switch Pro back on.'=>'Ta licencja była dołączona bezpłatnie do hostingu Zinn® i ten hosting dobiegł końca. Kup licencję lub zacznij ponownie korzystać z naszego hostingu, aby włączyć wersję Pro z powrotem.','Every site on this licence is in use. Release one below, or upgrade to cover more sites.'=>'Każda strona w ramach tej licencji jest używana. Zwolnij jedną poniżej lub uaktualnij plan, aby objąć większą liczbę stron.','We could not confirm your licence just now. Nothing has changed on your site; we will try again shortly.'=>'Nie udało nam się w tej chwili potwierdzić Państwa licencji. Nic nie zmieniło się na Państwa stronie; spróbujemy ponownie wkrótce.','You do not have permission to manage licences on this site.'=>'Nie masz uprawnień do zarządzania licencjami w tej witrynie.','Your Pro licence'=>'Twoja licencja Pro','Licence key'=>'Klucz licencji','Copy it from the Licences page of your %s.'=>'Skopiuj ją ze strony Licencje w swoim panelu %s.','Renews on %s.'=>'Odnowienie: %s.','Using %1$d of %2$d sites.'=>'Wykorzystano %1$d z %2$d witryn.','In use on: %s. Release one from your dashboard, then try again.'=>'Używane na: %s. Zwolnij jedno z pulpitu, a następnie spróbuj ponownie.','Save licence'=>'Zapisz licencję','Remove it from this site'=>'Usuń tę witrynę','Where the chat appears'=>'Gdzie pojawia się czat','Show it'=>'Pokaż to','Everywhere on this site'=>'Wszędzie w tej witrynie','Only on the pages I choose below'=>'Tylko na stronach, które wybiorę poniżej','Everywhere except the pages I choose below'=>'Wszędzie oprócz stron wybranych poniżej','Page or post IDs'=>'Identyfikatory stron lub wpisów','Separate them with commas. The ID is in the address bar while you edit a page.'=>'Rozdziel je przecinkami. Identyfikator znajduje się w pasku adresu podczas edycji strony.','Whole content types'=>'Wszystkie typy zawartości','Signed-in visitors'=>'Zalogowani goście','Hide the chat from people who are signed in to this site'=>'Ukryj czat przed osobami zalogowanymi w tej witrynie','Save where it appears'=>'Zachowaj tam, gdzie się pojawia']];